-- id=43  أبو عبيدة بن الجراح (عامر بن عبد الله)
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 43;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'عامر بن عبد الله بن الجراح بن هلال بن أهيب بن ضبة بن الحارث بن فهر بن مالك بن النضر بن كنانة بن خزيمة
أبو عبيدة اشتهر بكنيته ونسبه إلى جده فيقال أبو عبيدة بن الجراح وهو أحد العشرة المشهود لهم بالجنة وشهد بدرا وأحدا والمشاهد كلها مع رسول الله صلى الله عليه وسلم وهو من السابقين إلى الإسلام وهاجر إلى الحبشة وإلى المدينة أيضا وكان يدعى القوي الأمين وكان أهتم وسبب ذلك أنه نزع الحلقتين اللتين دخلتا في وجه رسول الله صلى الله عليه وسلم من المغفر يوم أحد فانتزعت ثنيتاه فحسنتا فاه فما رؤى أهتم قط أحسن منه وقال له أبو بكر الصديق يوم السقيفة قد رضيت لكم أحد هذين الرجلين عمر بن الخطاب وأبو عبيدة بن الجراح وكان أحد الأمراء المسيرين إلى الشام والذين فتحوا دمشق ولما ولي عمر بن الخطاب الخلافة عزل خالد بن الوليد واستعمل أبا عبيدة فقال خالد ولي عليكم أمين هذه الأمة وقال أبو عبيدة سمعت رسول الله صلى الله عليه وسلم يقول إن خالدا لسيف من سيوف الله ولما كان أبو عبيدة يبدر يوم الوقعة جعل أبوه يتصدى له وجعل أبو عبيدة يحيد عنه فلما أكثر أبوه قصده فقتله أبو عبيدة فأنزل الله تعالى لا تجد قوما يؤمنون بالله واليوم الآخر يوادون من حاد الله ورسوله ولو كانوا آباءهم أو أبناءهم الآية وان الواقدي ينكر هذا ويقول توفي أبو أبي عبيدة قبل الإسلام وقد رد بعض أهل العلم قول الواقدي أخبرنا إسماعيل بن علي بن عبيد الله وغيره قالوا بإسنادهم إلى أبي عيسى الترمذي قال حدثنا عبد الله بن معاوية الجمحي حدثنا حماد بن سلمة عن خالد الحذاء عن عبد الله بن شقيق عن عبد الله بن سراقة عن أبي عبيدة بن الجراح قال سمعت رسول الله صلى الله عليه وسلم يقول أنه لم يكن نبي بعد نوح إلا وقد أنذر قومه الدجال وإني أنذركموه فوصفه لنا رسول الله صلى الله عليه وسلم فقال لعله يدركه بعض من رآني وسمع كلامي قالوا يا رسول الله فكيف قلوبنا يومئذ قال مثلها يعني اليوم أو خير أخبرنا أبو الفضل المخزومي الطبري بإسناده إلى أبي يعلى أحمد بن علي حدثنا أبو بكر بن أبي شيبة وأبو خيثمة قالا حدثنا إسماعيل بن علية عن خالد عن أبي قلابة قال قال أنس قال رسول الله صلى الله عليه وسلم لكل أمة أمين وإن أميننا أيتها الأمة أبو عبيدة بن الجراح أخبرنا أبو الفضل عبد الله بن أحمد الخطيب أخبرنا أبو بكر أحمد بن علي بن بدران الحلواني أخبرنا القاضي أبو الطيب الطبري أخبرنا أبو أحمد الغطريفي أخبرنا أبو خليفة الجمحي أخبرنا سليمان بن حرب حدثنا شعبة عن خالد الحذاء عن أبي قلابة 
عن أنس إنه قال لكل أمة أمين وأمين هذه الأمة أبو عبيدة بن الجراح ولما هاجر أبو عبيدة بن الجراح إلى المدينة آخى رسول الله صلى الله عليه وسلم بينه وبين أبي طلحة الأنصاري وأخبرنا أبو محمد بن أبي القاسم بن عساكر الدمشقي إجازة أخبرنا أبي أخبرنا أبو غالب بن المثنى حدثنا أبو محمد الجوهري أخبرنا أبو عمر بن حيويه وأبو بكر بن إسماعيل قالا حدثنا يحيى بن محمد بن صاعد حدثنا الحسين بن الحسن أخبرنا عبد الله بن مبارك حدثنا معمر عن هشام بن عروة عن أبيه قال قدم عمر ابن الخطاب الشام فتلقاه أمراء الأجناد وعظماء أهل الأرض فقال عمر أين أخي قالوا من قال أبو عبيدة قالوا يأتيك الآن قال فجاء على ناقة مخطومة بحبل فسلم عليه وسأله ثم قال للناس انصرفوا عنا فسار معه حتى أتى منزله فنزل عليه فلم ير في بيته إلا سيفه وترسه فقال عمر لو اتخذت متاعا أو قال شيئا قال أبو عبيدة يا أمير المؤمنين إن هذا سيبلغنا المقيل قال وحدثنا معمر عن قتادة قال قال أبو عبيدة بن الجراح لوددت أني كبش يذبحني أهلي فيأكلون لحمي ويحسون مرقي قال وقال عمران بن حصين لوددت أني كنت رمادا تسفيني الريح في يوم عاصف حثيث وروى عنه العرباض بن سارية وجابر بن عبد الله وأبو أمامة الباهلي وأبو ثعلبة الخشي وسمرة بن جندب وغيرهم وقال عروة بن الزبير لما نزل طاعون عمواس كان أبو عبيدة معافى منه وأهله فقال اللهم نصيبك في آل أبي عبيدة قال فخرجت بأبي عبيدة في خنصرة بثرة فجعل ينظر إليها فقيل له إنها ليست بشئ فقال إني لأرجو أن يبارك الله فيها فإنه إذا بارك في القليل كان كثيرا وقال عروة بن رويم أن أبا عبيدة بن الجراح انطلق يريد الصلاة ببيت المقدس فأدركه أجله بفحل فتوفي بها وقيل إن قبره ببيسان وقيل توفي بعمواس سنة ثمان عشر وعمره ثمان وخمسون سنة وكان يخضب رأسه ولحيته بالحناء والكتم وبين عمواس والرملة أربعة فراسخ فما يلي البيت المقدس وقد انقرض ولد أبي عبيدة ولما حضره الموت استخلف معاذ بن جبل على الناس أخرجه الثلاثة'
WHERE id = 43
  AND content_ar LIKE '(ب د ع) عامر بن عبد %'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 43;


-- الخطوة 2 (v2: LIKE بالبداية + معاملة مستقلة لكل صف) - دفعة 10/31 (1 صفوف)

-- id=44  خديجة بنت خويلد
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 44;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'خديجة بنت خويلد بن أسد بن عبد العزى بن قصي القرشية الأسدية أم المؤمنين زوج النبي صلى الله عليه وسلم أول امرأة تزوجها وأول خلق الله أسلم بإجماع المسلمين لم يتقدمها رجل ولا امرأة قال الزبير كانت تدعى في الجاهلية الطاهرة وأمها فاطمة بنت زائدة بن الأصم واسمه جندب بن هرم بن رواحة ابن حجر بن عبد بن معيص بن عامر بن لؤي وكانت خديجة قبل رسول الله صلى الله عليه وسلم تحت أبي هالة بن زرارة بن نباش بن عدي بن حبيب بن صرد بن سلامة بن جروة بن أسيد بن عمرو بن تميم التميمي كذا نسبه الزبير وقال علي بن عبد العزيز الجرجاني كانت خديجة عند أبي هالة هند بن النباش بن زرارة بن وقدان بن حبيب بن سلامة بن جروة بن أسيد بن عمرو بن تميم ثم اتفقا فقالا ثم خلف عليها بعد أبي هالة عتيق بن عائذ بن عبد الله بن عمر بن مخروم المخزومي ثم خلف عليها بعد عتيق رسول الله صلى الله عليه وسلم وقال قتادة كانت خديجة تحت عتيق بن عائذ بن عبد الله بن عمرو بن مخزوم ثم خلف عليها بعده أبو هالة هند بن زرارة بن النباش قال قتادة والقول الأول أصح إن شاء الله تعالى قاله أبو عمر وروى يونس بن بكير عن ابن إسحاق قال وتزوج خديجة قبل رسول الله صلى الله عليه وسلم وهي بكر عتيق بن عائذ بن عبد الله بن عمر بن مخزوم ثم هلك عنها فتزوجها بعده أبو هالة النباش بن زرارة قال وكانت خديجة قبل أن ينكحها رسول الله صلى الله عليه وسلم تحت عتيق بن عائذ بن عبد الله فولدت له هند بنت عتيق ثم خلف عليها بعد عتيق أبو هالة مالك بن النباش بن زرارة التميمي الأسدي حليف بني عبد الدار بن قصي فولدت له هند بنت أبي هالة وهالة بن أبي هالة فهند بنت عتيق وهند وهالة ابنا أبي هالة كلهم إخوة أولاد رسول الله صلى الله عليه وسلم من خديجة كل ذلك ذكره الزبير وهذا عكس ما نقله أبو عمر عن الزبير فإن أبا عمر نقل عن الزبير أنها كانت عند أبي هالة أولا ثم بعده عند عتيق ونقل أبو نعيم عن الزبير فقدم عتيقا على أبي هالة وأما الذي رويناه في نسب قريش للزبير قال وكانت يعني خديجة قبل النبي صلى الله عليه وسلم عند عتيق بن عائذ بن عبد الله
ابن عمر بن مخزوم فولدت له جارية وهلك عنها عتيق فتزوجها أبو هالة بن مالك أحد بني عمرو بن تميم ثم أحد بني أسد قال الزبير وبعض الناس يقول أبو هالة قبل عتيق وتزوج رسول الله صلى الله عليه وسلم خديجة رضي الله عنها قبل الوحي وعمره حينئذ خمس وعشرون سنة وقيل إحدى وعشرون سنة زوجها منه عمها عمرو بن أسد ولما خطبها رسول الله صلى الله عليه وسلم قال عمها محمد بن عبد الله بن عبد المطلب يخطب خديجة بنت خويلد هذا الفحل لا يقدع أنفه وكان عمرها حينئذ أربعين سنة وأقامت معه أربعا وعشرين سنة كان سبب تزوجها برسول الله صلى الله عليه وسلم ما أخبرنا أبو جعفر بإسناده عن يونس عن ابن إسحاق قال كانت خديجة امرأة تاجرة ذات شرف ومال تستأجر الرجال في مالها تضاربهم إياه بشئ تجعله منه فلما بلغها عن رسول الله صلى الله عليه وسلم ما بلغها من صدق حديثه وعظم أمانته وكرم أخلاقه بعثت إليه وعرضت عليه أن يخرج في مالها إلى الشام تاجرا وتعطيه أفضل ما كانت تعطي غيره من التجار مع غلام لها يقال له ميسرة فقبله منها وخرج في مالها ومعه غلامها ميسرة حتى قدم الشام فنزل رسول الله صلى الله عليه وسلم في ظل شجرة قريبا من صومعة راهب فاطلع الراهب إلى ميسرة فقال من هذا الرجل الذي نزل تحت هذه الشجرة قال هذا رجل من قريش من أهل الحرم فقال له الراهب ما نزل تحت هذه الشجرة قط إلا نبي ثم باع رسول الله صلى الله عليه وسلم سلعته التي خرج بها واشترى ما أراد ثم أقبل قافلا إلى مكة فلما قدم على خديجة بمالها باعت ما جاء به فأضعف أو قريبا وحدثها ميسرة عن قول الراهب وكانت خديجة امرأة حازمة لبيبة شريفة مع ما أراد الله بها من كرامتها فلما أخبرها ميسرة بعثت إلى رسول الله صلى الله عليه وسلم فقالت له إني قد رغبت فيك لقرابتك مني وشرفك في قومك وأمانتك عندهم وحسن خلقك وصدق حديثك ثم عرضت عليه نفسها وكانت أوسط نساء قريش نسبا وأعظمهم شرفا وأكثرهم مالا فلما قالت لرسول الله صلى الله عليه وسلم ما قالت ذكر ذلك لأعمامه فخرج معه حمزة بن عبد المطلب حتى دخل على خويلد بن أسد فخطبها إليه فتزوجها رسول الله صلى الله عليه وسلم فولدت لرسول الله صلى الله عليه وسلم ولده كلهم قبل أن ينزل عليه الوحي زينب وأم كلثوم وفاطمة ورقية والقاسم والطاهر والطيب فأما القاسم والطيب والطاهر فهلكوا قبل الإسلام وبالقاسم كان يكنى رسول الله صلى الله عليه وسلم وأما بناته فأدركن الإسلام فهاجرن معه واتبعنه وآمن به وقيل إن الطاهر والطيب ولدا في الإسلام وقد تقدم أن عمها عمر أزوجها وأن أباها كان قد مات قاله الزبير وغيره واختلف العلماء في أولاد رسول الله صلى الله عليه وسلم منها فروى معمر عن الزهري قال زعم بعض العلماء أنها ولدت له ولدا يسمى الطاهر وقال قال بعضهم ما نعلمها ولدت له إلا القاسم وبناته الأربع وقال عقيل عن ابن شهاب وذكر بناته وقال والقاسم والطاهر وقال قتادة ولدت له خديجة غلامين وأربع بنات القاسم وبه كان يكنى وعاش حتى مشى وعبد الله مات صغيرا وقال الزبير ولدت لرسول الله صلى الله عليه وسلم القاسم وهو أكبر ولده ثم زينب ثم عبد الله وكان يقال له الطيب ويقال له الطاهر ثم مات القاسم بمكة وهو أول ميت مات من ولده ثم عبد الله مات أيضا بمكة وقال الزبير أيضا حدثني إبراهيم بن المنذر عن ابن وهب عن ابن لهيعة عن أبي الأسود محمد بن عبد الرحمن إن خديجة بنت خويلد ولدت لرسول الله صلى الله عليه وسلم القاسم والطاهر والطيب وعبد الله وزينب ورقية وأم كلثوم وفاطمة وقال علي بن عبد العزيز الجرجاني أولاد رسول الله صلى الله عليه وسلم القاسم وهو أكبر ولده ثم زينب قال وقال الكلبي زينب والقاسم ثم أم كلثوم ثم فاطمة ثم رقية ثم عبد الله وكان يقال له الطيب والطاهر قال وهذا هو الصحيح وغيره تخليط وقال الكلبي ولد عبد الله في الإسلام وكل ولده منها ولد قبل الإسلام وأما إسلامها فأخبرنا محمد بن سرايا بن علي وغير واحد بإسنادهم إلى محمد بن إسماعيل حدثنا يحيى بن بكير أخبرنا الليث عن عقيل عن ابن شهاب عن عروة عن عائشة أم المؤمنين قالت أول ما بدئ به رسول الله صلى الله عليه وسلم من الوحي الرؤيا الصالحة في النوم كان لا يرى رؤيا إلا جاءت مثل فلق الصبح وذكر الحديث قال يعني جبريل عليه السلام اقرأ باسم ربك الذي خلق فرجع بها رسول الله صلى الله عليه وسلم يرجف فؤاده فدخل على خديجة رضي الله عنها فقال زملوني فزملوه حتى ذهب عنه الروع وقال لخديجة وأخبرها الخبر لقد خشيت على نفسي فقالت خديجة كلا والله لا يخز بك الله أبدا إنك لتصل الرحم وتحمل الكل وتكسب المعدوم وتفرى الضيف وتعين على نوائب الحق وانطلقت به خديجة إلى ورقة بن نوفل وكان أمرأ تنصر في الجاهلية ويكتب الكتاب العبراني ويكتب من الإنجيل ما شاء الله أن يكتب فقالت له خديجة يا ابن عم اسمع من ابن أخيك فقال له ورقة ماذا ترى فأخبره رسول الله صلى الله عليه وسلم فقال يا ليتني فيها جذعا ليتني أكون حيا إذ يخرجك قومك أخبرنا أبو جعفر بإسناده إلى يونس عن ابن إسحاق قال وكانت خديجة أول من آمن بالله ورسوله وصدق بما جاء به فخفف الله بذلك عن رسول الله صلى الله عليه وسلم لا يسمع شيئا يكرهه من رد عليه وتكذيب له فيحزنه إلا فرج الله عنه بها إذا رجع إليها تثبته وتخفف عنه وتصدقه وتهون عليه أمر الناس رضي الله عنها قال ابن إسحاق وحدثني إسماعيل بن أبي حكيم مولى والزبير أنه حدث عن خديجة أنها قالت لرسول الله صلى الله عليه وسلم يا ابن عم هل تستطيع أن تخبرني بصاحبك الذي يأتيك إذا جاءك قال نعم فبينا رسول الله صلى الله عليه وسلم عندها إذ جاءه جبريل فقال رسول الله صلى الله عليه وسلم هذا جبريل قد جاءني فقالت أتراه الآن قال نعم قالت اجلس على شقي الأيسر فجلس فقالت هل تراه الآن قال نعم قالت فاجلس على شقي الأيمن فجلس فقالت هل تراه قال نعم قالت فتحول فاجلس في حجري فتحول رسول الله صلى الله عليه وسلم فجلس فقالت هل تراه قال نعم قال فتحسرت وألقت خمارها فقالت هل تراه قال لا قالت ما هذا شيطان إن هذا لملك يا ابن عم اثبت وأبشر ثم آمنت به وشهدت أن الذي جاء به الحق أخبرنا أبو محمد عبد الله بن علي أخبرنا أبو الفضل بن ناصر أخبرنا أبو صالح أحمد بن عبد الملك المؤذن أخبرنا الحسين بن فاذشاه أخبرنا أبو القاسم الطبراني أخبرنا القاسم بن زكريا المطرز أخبرنا يوسف بن موسى القطان أخبرنا تميم بن الجعد أخبرنا أبو جعفر الرازي عن ثابت عن أنس قال قال رسول الله صلى الله عليه وسلم خير نساء العالمين مريم بيت عمران وآسية بنت مزاحم امرأة فرعون قال في اصل الشيخ داود مصلح ورواه عارم داود بن أبي الفرات عن علباء بن أحمر أخبرنا إبراهيم وإسماعيل وغيرهما بإسنادهم عن محمد بن عيسى أخبرنا الحسن بن حريث حدثنا الفضل بن موسى عن هشام بن عروة عن أبيه عن عائشة أن رسول الله صلى الله عليه وسلم بشر خديجة ببيت في الجنة من قصب لا صخب فيه ولا نصب أخبرنا يحيى بن محمود وعبد الوهاب ابن أبي حبة بإسنادهما إلى مسلم حدثنا أبو كريب أخبرنا أبو أسامة عن هشام عن أبيه عن عبد الله بن جعفر قال سمعت علي بن أبي طالب رضي الله عنه يقول سمعت رسول الله صلى الله وسلم يقول خير نسائها خديجة بنت خويلد وخير نسائها مريم بنت عمران قال أبو كريب وأشار وكيع إلى السماء والأرض أخبرنا أبو الفضل عبد الله بن أحمد بن محمد الطوسي أخبرنا جعفر بن أحمد السراج أخبرنا أبو علي بن شاذان أخبرنا أبو عمرو عثمان بن أحمد الدقاق أخبرنا ابن أبي العوام أخبرنا الوليد بن القاسم أخبرنا إسماعيل بن أبي خالد عن ابن أبي أوفى أن رسول الله صلى الله عليه وسلم بشر خديجة ببيت في الجنة من قصب لا نصب فيه ولا صخب وأخبرنا عبد الله بن أحمد أخبرنا أبو بكر بن بدران الحلواني قال قرئ على أبي الحسين محمد بن أحمد بن محمد الأبنوسي وأنا أسمع أخبركم أبو الحسين محمد بن عبد الرحمن بن جعفر الدينوري فأقر به أخبرنا أبو بكر محمد بن عبد الله بن غيلان الخزاز أخبرنا أبو هشام الرفاعي أخبرنا حفص بن غياث عن هشام بن عروة عن أبيه عن عائشة قالت ما غرت على أحد من أزواج النبي ما غرت على خديجة وما بي أن أكون أدركتها وما ذاك إلا لكثرة ذكر رسول الله صلى الله عليه وسلم لها وإن كان مما تذبح الشاة يتبع بها صدائق خديجة فيهديها لهن وأخبرنا يحيى بن محمود وأبو ياسر بإسنادهما عن مسلم قال حدثنا أبو بكر بن أبي شيبة وأبو كريب وابن نمير قالوا حدثنا ابن فضيل عن عمارة عن أبي زرعة قال سمعت أبا هريرة يقول قال رسول الله صلى الله عليه وسلم أتاني جبريل عليه السلام فقال يا رسول الله هذه خديجة قد أتتك ومعها إناء فيه إدام أو طعام أو شراب فإذا هي أتتك فاقرأ عليها¬ السلام من ربها ومني وبشرها ببيت في الجنة من قصب لا صخب فيه ولا نصب قال أبو بكر في روايته عن أبي هريرة ولم يقل سمعت ولم يقل في الحديث ومني وروى مجالد عن الشعبي عن مسروق عن عائشة قالت كان رسول الله صلى الله عليه وسلم لا يكاد يخرج من البيت حتى يذكر خديجة فيحس الثناء عليها فذكرها يوما من الأيام فأدركتني الغيرة فقلت هل كانت إلا عجوز فقد أبدلك الله خير منها فغضب حتى أهتز مقدم شعره من الغضب ثم قال لا والله ما أبدلني الله خيرا منها آمنت إذ كفر الناس وصدقتني وكذبني الناس 
وواستني في مالها إذ حرمني الناس ورزقني الله منها أولاد إذ حرمني أولاد النساء قالت عائشة فقلت في نفسي لا أذكرها بسيئة أبدا وروى الزبير بن بكار عن محمد ابن الحسن عن يعلى بن المغيرة عن ابن أبي رواد قال دخل رسول الله صلى الله عليه وسلم على خديجة في مرضها الذي ماتت فيه فقال لها بالكره منى ما ثنى عليك يا خديجة وقد يجعل الله في الكره خيرا كثيرا أما علمت إن الله تعالى زوجني معك في الجنة مريم بنت عمران وكلثم أخت موسى وآسية امرأة فرعون فقالت وقد فعل ذلك يا رسول الله قال نعم قالت بالرفاء والبنين أخبرنا عبيد الله بن أحمد بإسناده عن يونس عن ابن إسحاق قال ثم إن خديجة توفيت بعد أبي طالب وكانا ماتا في عام واحد فتتابعت على رسول الله صلى الله عليه وسلم المصائب بهلاك خديجة وأبي طالب وكانت خديجة وزيرة صدق على الإسلام سنين وقيل بأربع سنين وقال عروة وقتادة توفيت قبل الهجرة بثلاث سنين وهذا هو الصواب وقالت عائشة توفيت خديجة قبل أن تفرض الصلاة قيل إن وفاة خديجة كانت بعد أبي طالب بثلاث أيام وكان موتها في رمضان ودفنت بالحجون قيل كان عمرها خمسا وستين سنة أخرجها الثلاثة'
WHERE id = 44
  AND content_ar LIKE '(ب د ع) خديجة بنت خو%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 44;


