-- id=45  سودة بنت زمعة
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 45;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'سودة بنت زمعة بن قيس بن عبد شمس بن عبد ود بن نصر بن مالك بن حسل بن عامر بن لؤي القرشية العامرية وأمها الشموس بنت قيس بن زيد بن عمرو بن لبيد بن خراش بن عامر بن غنم بن عدي بن النجار الأنصارية وسودة هي زوج النبي صلى الله عليه وسلم تزوجها رسول الله صلى الله عليه وسلم بمكة بعد وفاة خديجة قبل عائشة قاله عقيل عن الزهري وقاله قتادة وأبو عبيدة وابن إسحاق وقال عبد الله بن محمد بن عقيل تزوجها بعد عائشة ورواه يونس عن الزهري وكانت قبله تحت ابن عمها السكران بن عمرو أخي سهيل بن عمرو من بني عامر بن لؤي وكان مسلما فتوفي عنها فتزوجها رسول الله صلى الله عليه وسلم وكانت امرأة ثقيلة ثبطة وأسنت عند رسول الله صلى الله عليه وسلم ولم تصب منه ولدا إلى أن مات وروى محمد بن إسحاق عن حكيم بن حكيم عن محمد بن علي بن الحسين عن أبيه قال كان جميع ما تزوج رسول الله صلى الله عليه وسلم خمس عشرة امرأة وكان أول امرأة تزوجها بعد خديجة بنت خويلد سودة بنت زمعة أخبرنا غير واحد بإسنادهم عن محمد بن عيسى قال حدثنا محمد بن المثنى أخبرنا أبو داود الطيالسي أخبرنا سليمان بن معاذ عن سماك عن عكرمة عن ابن عباس قال خشيت سودة أن

يطلقها رسول الله صلى الله عليه وسلم فقالت لا تطلقني وأمسكني واجعل يومي لعائشة ففعل فنزلت فلا جناح عليهما أن يصالحا بينهما صلحا والصلح خير فما اصطلحا عليه من شئ فهو جائز أخبرنا عبد الوهاب بن هبة الله بإسناده عن عبد الله حدثني أبي حدثنا عبد العزيز بن عبد الصمد العمي أبو عبد الصمد حدثنا منصور عن مجاهد مولى لابن الزبير يقال له يوسف بن الزبير أو الزبير بن يوسف عن ابن الزبير عن سودة بنت زمعة قالت جاء رجل إلى رسول الله صلى الله عليه وسلم فقال إن أبي شيخ كبير لا يستطيع أن يحج قال أرأيت لو كان على أبيك دين فقضيته عنه قبل منك قال نعم قال فالله أرحم حج عن أبيك وتوفيت سودة آخر خلافة عمر أخرجها الثلاثة'
WHERE id = 45
  AND content_ar LIKE '(ب د ع) سودة بنت زمع%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 45;

-- id=46  عائشة بنت أبي بكر الصديق
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 46;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'عائشة بنت أبي بكر الصديق الصديقة بنت الصديق أم المؤمنين زوج النبي صلى الله عليه وسلم وأشهر نسائه وأمها أم رومان ابنه عامر بن عويمر بن عبد شمس بن أذينة بن سبيع بن دهمان بن الحارث بن غنم بن مالك بن كنانة الكنانية تزوجها رسول الله صلى الله عليه وسلم قبل الهجرة بسنتين وهي بكر قاله أبو عبيدة وقيل بثلاث سنين وقال الزبير تزوجها رسول الله صلى الله عليه وسلم بعد خديجة بثلاث سنين وتوفيت خديجة قبل الهجرة بثلاث سنين وقيل بأربع سنين وقيل بخمس سنين وكان عمرها
لما تزوجها رسول الله صلى الله عليه وسلم ست سنين وقيل سبع سنين وبنى بها وهي بنت تسع سنين بالمدينة وكان جبريل قد عرض على رسول الله صلى الله عليه وسلم صورتها في سرقة حرير في المنام لما توفيت خديجة وكناها رسول الله صلى الله عليه وسلم أم عبد الله بابن أختها عبد الله بن الزبير أخبرنا يحيى بن محمود فيما أذن لي بإسناده عن ابن أبي عاصم قال حدثنا سعيد بن يحيى بن سعيد حدثنا أبي عن محمد ابن عمرو عن يحيى بن عبد الرحمن عن حاطب عن عائشة قالت لما توفيت خديجة قالت خولة بنت حكيم بن الأوقص امرأة عثمان بن مظعون وذلك بمكة أي رسول الله ألا تزوج قال ومن قلت إن شئت بكرا وإن شئت ثيبا قال فمن البكر قلت ابنة أحب خلق الله إليك عائشة بنت أبي بكر قال ومن الثيب قلت سودة بنت زمعة بن قيس آمنت بك واتبعتك على ما أنت عليه قال فاذهبي فاذكريهما علي فجاءت فدخلت بيت أبي بكر فوجدت أم رومان أم عائشة فقالت أي أم رومان ما أدخل الله عليكم من الخير والبركة قالت وما ذاك قالت أرسلني رسول الله صلى الله عليه وسلم أخطب عليه عائشة قالت وهل تصلح له انما هي ابنة أخيه وددت انتظري أبا بكر فإنه آت فجاء أبو بكر فقالت يا أبا بكر ماذا أدخل الله عليكم من الخير والبركة قال وما ذاك قالت أرسلني رسول الله صلى الله عليه وسلم أخطب عليه عائشة قال وهل تصلح له إنما هي بنت أخيه فرجعت إلى رسول الله صلى الله عليه وسلم فذكرت ذلك له فقال ارجعي وقولي له أنت أخي في الإسلام وابنتك تصلح لي فأتت أبا بكر فقال ادعي لي رسول الله صلى الله عليه وسلم فجاء فأنكحه وهي يومئذ بنت ست سنين وقال رسول الله صلى الله عليه وسلم ومن الثيب قالت سودة بنت زمعة قد آمنت بك واتبعتك قال اذهبي فاذكريها علي قالت فخرجت فدخلت على سودة فقلت يا سودة ما أدخل الله عليكم من الخير والبركة قالت وما ذاك قالت أرسلني رسول الله صلى الله عليه وسلم أخطبك عليه قالت وددت أدخلي على أبي فاذكري ذلك له قالت وهو شيخ كبير قد تخلف عن الحج فدخلت عليه فقلت أن محمد بن عبد الله أرسلني أخطب عليه سودة قال كفؤ كريم فماذا تقول صاحبتك قالت تحب ذلك قال ادعيها فدعتها فقال أن محمد بن عبد الله أرسل يخطبك وهو كفؤ كريم أفتحبين أن أزوجك قالت نعم قال فادعيه لي فدعته فجاء فزوجها وجاء أخوها عبد بن زمعة من الحج فجعل يحثو التراب على رأسه وقال بعد أن أسلم إني لسفيه يوم أحثو التراب على رأسي أن تزوج رسول الله صلى الله عليه وسلم سودة أخبرنا أبو الفرج بن أبي الرجاء أخبرنا أبو علي الحداد وأنا حاضر أسمع أخبرنا أحمد بن عبد الله الحافظ أخبرنا فاروق أخبرنا محمد بن محمد بن حيان التمار أخبرنا عبد الله بن مسلمة القعنبي حدثنا سليمان بن بلال عن أبي طوالة عن أنس بن مالك قال قال رسول الله صلى الله عليه وسلم فضل عائشة على النساء كفضل الثريد على سائر الطعام أخبرنا محمد بن سرايا بن علي العدل والحسين بن أبي صالح بن فناخسرو وغيرهما بإسنادهم عن محمد ابن إسماعيل حدثنا عبد الله بن عبد الوهاب أخبرنا حماد أخبرنا هشام عن أبيه قال كان الناس يتحرون بهداياهم يوم عائشة قالت فاجتمع صواحبي إلى أم سلمة فقالوا يا أم سلمة أن الناس يتحرون بهداياهم يوم عائشة وإنا نريد من الخير كما تريد عائشة فمري رسول الله صلى الله عليه وسلم إن يأمر الناس أن يهدوا إليه حيث ما كان أو حيث ما دار قالت فذكرت ذلك أم سلمة للنبي صلى الله عليه وسلم قالت فأعرض عني فلما عاد إلى ذكرت له ذلك فأعرض عني فلما كان في الثالثة ذكرت له ذلك فقال يا أم سلمة لا تؤذيني في عائشة فإنه والله ما نزل علي الوحي وأنا في لحاف امرأة منكن غيرها قال وحدثنا محمد بن إسماعيل حدثنا يحيى بن بكير أخبرنا الليث عن يونس عن ابن شهاب قال قال أبو سلمة أن عائشة قالت قال رسول الله صلى الله عليه وسلم يوما يا عائش هذا جبريل يقرئك السلام فقلت وعليه¬ السلام ورحمة الله وبركاته ترى ما لا أرى أخبرنا إسماعيل بن علي وإبراهيم بن محمد وغيرهما بإسنادهم عن محمد بن عيسى قال حدثنا عبد بن حميد أخبرنا عبد الرزاق عن عبد الله بن عمرو بن علقمة المكي عن ابن أبي حسين عن ابن أبي مليكة عن عائشة أن جبريل جاء بصورتها في خرقة حرير خضراء إلى النبي صلى الله عليه وسلم فقال هذه زوجتك في الدنيا والآخرة قال وحدثنا محمد بن عيسى حدثنا بندار وإبراهيم بن يعقوب قالا حدثنا يحيى بن حماد حدثنا عبد العزيز بن المختار أخبرنا خالد الحذاء عن أبي عثمان الهدى عن عمرو بن العاص أن رسول الله صلى الله عليه وسلم استعمله على جيش ذات السلاسل قال فأتيته فقلت يا رسول الله أي الناس أحب إليك قال عائشة قلت من الرجال قال أبوها قال وحدثنا محمد بن عيسى حدثنا محمد بن بشار أخبرنا عبد الرحمن ابن مهدي حدثنا سفيان عن أبي إسحاق عن عمرو بن غالب أن رجلا نال من عائشة رضي الله عنها عند عمار بن ياسر فقال اغرب مقبوحا منبوحا أتؤذي حبيبة 
رسول الله صلى الله عليه وسلم وكان مسروق إذا روى عنها يقول حدثتني الصديقة بنت الصديق البريئة المبرأة وكان أكابر الصحابة يسألونها عن الفرائض وقال عطاء ابن أبي رباح كانت عائشة من أفقه الناس وأحسن الناس رأيا في العامة وقال عروة ما رأيت أحدا أعلم بفقه ولا بطب ولا بشعر من عائشة ولو لم يكن لعائشة من الفضائل إلا قصة الإفك لكفى بها فضلا وعلو مجد فإنها نزل فيها من القرآن ما يتلى إلى يوم القيامة ولولا خوف التطويل لذكرنا قصة الإفك بتمامها وهي أشهر من أن تخفى أخبرنا مسمار بن عمر بن العويس وأبو الفرج محمد بن عبد الرحمن بن أبي العز وغيرهما بإسنادهم عن محمد بن إسماعيل حدثنا محمد بن بشار أخبرنا عبد الوهاب بن عبد المجيد حدثنا ابن عون عن القاسم بن محمد أن عائشة اشتكت فجاء ابن عباس فقال يا أم المؤمنين تقدمين على فرط صدق على رسول الله صلى الله عليه وسلم وعلى أبي بكر وروت عن النبي صلى الله عليه وسلم كثيرا روى عنها عمر بن الخطاب وكثير من الصحابة ومن التابعين ما لا يحصى روى يحيى بن أيوب عن عبيد الله بن زحر عن علي بن زيد عن القاسم عن أبي أمامة أن عمر بن الخطاب قال أدنوا الخيل وانتضلوا وانتعلوا وإياكم وأخلاق الأعاجم وأن تجلسوا على مائدة يشرب عليها الخمر ولا يحل لمؤمن ولا مؤمنة تدخل الحمام إلا بمئزر إلا من سقم فإن عائشة حدثتني أن رسول الله صلى الله عليه وسلم قال وهو على فراشي أيما امرأة مؤمنة وضعت خمارها على غير بيتها هتكت الحجاب بينها وبين ربها عز وجل وتوفيت عائشة سنة سبع وخمسين وقيل سنة ثمان وخمسين ليلة الثلاثا لسبع عشرة ليلة خلت من رمضان وأمرت أن تدفن بالبقيع ليلا فدفنت وصلى عليها أبو هريرة ونزل في قبرها خمسة عبد الله وعروة ابنا الزبير والقاسم بن محمد بن أبي بكر وعبد الله بن محمد بن أبي بكر وعبد الله بن عبد الرحمن بن أبي بكر ولما توفي النبي صلى الله عليه وسلم كان عمرها ثمان عشرة سنة أخرجها الثلاثة'
WHERE id = 46
  AND content_ar LIKE '(ب د ع) عائشة بنت أب%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 46;

-- id=47  حفصة بنت عمر بن الخطاب
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 47;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'حفصة بنت عمر بن الخطاب رضي الله عنهما تقدم نسبها عند ذكر أبيها وهي من بني عدي بن كعب وأمها وأم أخيها عبد الله بن عمر زينب بنت مظعون أخت عثمان بن مظعون وكانت حفصة من المهاجرات وكانت قبل رسول الله صلى الله عليه وسلم تحت خنيس بن حذافة السهمي وكان ممن شهد بدرا وتوفي بالمدينة فلما تأيمت حفصة ذكرها عمر لأبي بكر وعرضها عليه فلم يرد عليه أبو بكر كلمة فغضب عمر من ذلك فعرضها على عثمان حين ماتت رقية بنت رسول الله صلى الله عليه وسلم فقال عثمان ما أريد أن أتزوج اليوم فانطلق عمر إلى رسول الله صلى الله عليه وسلم فشكا إليه عثمان فقال رسول الله صلى الله عليه وسلم يتزوج حفصة من هو خير من عثمان ويتزوج عثمان من هي خير من حفصة ثم خطبها إلى عمر فتزوجها رسول الله صلى الله عليه وسلم فلقي أبو بكر عمر رضي الله عنهما فقال لا تجد علي في نفسك فإن رسول الله صلى الله عليه وسلم ذكر حفصة فلم أكن لأفشي سر رسول الله صلى الله عليه وسلم فلو تركها لتزوجتها وتزوجها رسول الله صلى الله عليه وسلم سنة ثلاث عند أكثر العلماء وقال أبو عبيدة سنة اثنتين من التاريخ وتزوجها بعد عائشة وطلقها تطليقة ثم ارتجعها أمره جبريل بذلك وقال إنها صوامة قوامة وإنها

زوجتك في الجنة وروي موسى بن علي بن رباح عن أبيه عن عقبة بن عامر قال طلق رسول الله صلى الله عليه وسلم حفصة تطليقة فبلغ ذلك عمر فحثى التراب على رأسه وقال ما يعبأ الله بعمر وابنته بعدها فنزل جبريل عليه السلام وقال إن الله يأمرك أن تراجع حفصة بنت عمر رحمة لعمر أخبرنا أبو الفضل بن أبي الحسن المخزومي بإسناده عن أبي يعلى حدثنا أبو كريب أخبرنا يونس بن بكير عن الأعمش عن أبي صالح عن ابن عمر قال دخل عمر على حفصة وهي تبكي فقال لها ما يبكيك لعل رسول الله صلى الله عليه وسلم قد طلقك أنه قد كان طلقك مرة ثم راجعك من أجلي إن كان طلقك مرة أخرى لا أكلمك أبدا وأوصى عمر إلى حفصة بعد موته وأوصت حفصة إلى أخيها عبد الله بن عمر بما أوصى به إليها عمر وبصدقة تصدق بها بمال وقفته بالغابة روت عن النبي صلى الله عليه وسلم روى عنها أخوها عبد الله وغيره أخبرنا غير واحد بإسنادهم عن أبي عيسى قال حدثنا إسحاق بن منصور أخبرنا معن عن مالك عن ابن شهاب عن السائب بن يزيد عن المطلب بن أبي وداعة السهمي عن حفصة زوج النبي صلى الله عليه وسلم أنها قالت رأيت رسول الله صلى الله عليه وسلم صلى في سبحته قاعدا ويقرأ بالسورة فيرتلها حتى تكون أطول من أطول منها وأخبرنا أبو الحرم بن ريان بإسناده عن يحيى بن يحيى بن مالك عن نافع عن ابن عمر عن أخته حفصة أن رسول الله صلى الله عليه وسلم كان إذا سكت المؤذن من الأذان لصلاة الصبح صلى ركعتين خفيفتين قبل أن تقام الصلاة وتوفيت حفصة حين بايع الحسن بن علي رضي الله عنهما معاوية وذلك في جمادى الأولى سنة إحدى وأربعين وقيل توفيت سنة خمس وأربعين وقبل سنة سبع وعشرين أخرجها الثلاثة'
WHERE id = 47
  AND content_ar LIKE '(ب د ع) حفصة بنت عمر%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 47;


