-- id=51  جويرية بنت الحارث
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 51;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'جويرية بنت الحارث بن أبي ضرار بن حبيب بن عائذ بن مالك
ابن حذيمة وهو المصطلق بن سعد بن عمرو بن ربيعة بن حارثة بن عمرو مزيقيا وعمرو هو أبو خزاعة كلها الخزاعية المصطلقية سباها رسول الله صلى الله عليه وسلم يوم المريسيع وهي غزوة بني المصطلق سنة خمس وقيل سنة ست وكانت تحت مسافع بن صفوان المصطلقي فوقعت في سهم ثابت بن قيس بن شماس وابن عم له أخبرنا أبو جعفر عبيد الله بن أحمد بإسناده عن يونس بن بكير عن ابن إسحاق قال حدثني محمد بن جعفر بن الزبير عن عروة بن الزبير عن عائشة قالت لما قسم رسول الله صلى الله عليه وسلم سبايا بني المصطلق وقعت جويرية بنت الحارث في السهم لثابت بن قيس بن شماس أو لابن عم له فكاتبته على نفسها وكانت امرأة حلوة ملاحة لا يراها أحد إلا أخذت بنفسه فأتت رسول الله صلى الله عليه وسلم تستعينه في كتابتها قالت عائشة فوالله ما هو إلا أن رأيتها فكرهتها وقلت يرى منها ما قد رأيت فلما دخلت على رسول الله صلى الله عليه وسلم قالت يا رسول الله إنا جويرة بنت الحارث سيد قومه وقد أصابني من البلاء ما لم يخف عليك وقد كاتبت على نفسي فأعني على كتابتي فقال رسول الله صلى الله عليه وسلم أو خير من ذلك أؤدي عنك كتابتك وأتزوجك فقالت نعم ففعل رسول الله صلى الله عليه وسلم فبلغ الناس أنه قد تزوجها فقالوا أصهار رسول الله صلى الله عليه وسلم فأرسلوا ما كان في أيديهم من بني المصطلق فقد أعتق بها مائة أهل بيت من بني المصطلق فما أعلم امرأة أعظم بركة منها على قومها ولما تزوجها رسول الله صلى الله عليه وسلم حجبها وقسم لها وكان اسمها برة فسماها رسول الله صلى الله عليه وسلم جويرية رواه شعبة ومسعر وابن عيينة عن محمد بن عبد الرحمن مولى آل طلحة عن كريب مولى ابن عباس عن ابن عباس وروى إسرائيل عن محمد بن عبد الرحمن عن كريب عن ابن عباس قال كان اسم ميمونة برة فسماها رسول الله صلى الله عليه وسلم ميمونة قاله أبو عمر روت جويرية عن النبي صلى الله عليه وسلم روى عنها ابن عباس وجابر وابن عمر وعبيد بن السباق وغيرهم أخبرنا أبو جعفر بإسناده عن ابن إسحاق قال ثم تزوج رسول الله صلى الله عليه وسلم بعد زينب بنت جحش جويرية بنت الحارث وكانت قبله عند ابن عم لها يقال له ابن ذي الشفر فمات رسول الله صلى الله عليه وسلم ولم يصب منها ولدا أخبرنا إبراهيم بن محمد وغيره بإسنادهم عن أبي عيسى حدثنا محمد بن بشار أخبرنا محمد بن جعفر أخبرنا شعبة عن محمد بن عبد 
الرحمن قال سمعت كريبا يحدث عن ابن عباس عن جويرية بنت الحارث أن النبي صلى الله عليه وسلم مر عليها وهي في مسجدها ثم مر عليها قريبا من نصف النهار فقال لها ما زلت على حالك قالت نعم قال إلا أعلمك كلمات تقولينها سبحان الله عدد خلقه سبحان الله عدد خلقه سبحان الله عدد خلقه سبحان الله رضى نفسه سبحان الله رضى نفسه سبحان الله رضى نفسه سبحان الله زنة عرشه سبحان الله زنة عرشه سبحان الله زنة عرشه سبحان الله مداد كلماته سبحان الله مداد كلماته سبحان الله مداد كلماته أخرجها الثلاثة'
WHERE id = 51
  AND content_ar LIKE '(ب د ع) جويرية بنت ا%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 51;

