SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 52;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'رملة بنت أبي سفيان صخر بن حرب بن أمية بن عبد شمس أم حبيبة القرشية الأموية أم المؤمنين زوج رسول الله صلى الله عليه وسلم ورضي عنها وأمها صفية بنت أبي العاص عمة عثمان بن عفان بن أبي العاص قيل اسمها رملة وقيل هند اسلمت قديما بمكة وهاجرت إلى الحبشة مع زوجها عبد الله بن جحش فتنصر بالحبشة ومات بها وأبت هي أن تتنصر وثبتت على إسلامها فتزوجها رسول الله صلى الله عليه وسلم وهي بالحبشة زوجها منه عثمان بن عفان وقيل عقد عليها خالد بن سعيد ابن العاص بن أمية وأمهرها النجاشي عن رسول الله صلى الله عليه وسلم أربع مائة دينار وأولم عليها عثمان لحما وقيل أولم عليها النجاشي وحملها شرحبيل بن حسنة إلى المدينة وقد قيل أن رسول الله صلى الله عليه وسلم تزوجها وهي بالمدينة روى مسلم بن الحجاج في صحيحه أن أبا سفيان طلب من النبي صلى الله عليه وسلم أن يتزوجها فأجابه إلى ذلك وهذا مما يعد من أوهام مسلم لأن رسول الله صلى الله عليه وسلم كان قد تزوجها وهي بالحبشة قبل إسلام أبي سفيان لم يختلف أهل السير في ذلك ولما جاء أبو سفيان إلى المدينة قبل الفتح لما أوقعت قريش بخزاعة ونقضوا عهد رسول الله صلى الله عليه وسلم فخاف فجاء إلى المدينة ليجدد العهد فدخل على ابنته أم حبيبة فلم تتركه يجلس على فراش رسول الله صلى الله عليه وسلم وقالت أنت مشرك وقال قتادة لما عادت من الحبشة مهاجرة إلى المدينة خطبها رسول الله صلى الله عليه وسلم فتزوجها وكذلك روى الليث عن عقيل عن ابن شهاب وروى معمر عن الزهري أن رسول الله صلى الله عليه وسلم تزوجها وهي بالحبشة وهو أصح ولما بلغ الخبر إلى أبي سفيان أن رسول الله صلى الله عليه وسلم نكح أم حبيبة ابنته قال ذلك

الفحل لا يقدع أنفه وتزوجها رسول الله صلى الله عليه وسلم سنة ست وتوفيت سنة أربع وأربعين وقيل إن رسول الله صلى الله عليه وسلم أرسل عمرو بن أمية الضمري إلى النجاشي يخطب أم حبيبة فزوجها إياه وروى الزبير بن بكار قال حدثني محمد بن الحسن عن عبد الله بن عمرو بن زهير عن إسماعيل بن عمرو أن أم حبيبة قالت ما شعرت وأنا بأرض الحبشة إلا برسول النجاشي جارية فاستأذنت فأذنت لها فقالت إن الملك يقول لك إن رسول الله صلى الله عليه وسلم كتب إلى أن أزوجكيه فقلت بشرك الله بخير فقالت يقول الملك وكلي من يزوجك فأرسلت إلى خالد بن سعيد فوكلته فأمر النجاشي جعفر بن أبي طالب ومن هناك من المسلمين يحضرون وخطب النجاشي وقال أن رسول الله صلى الله عليه وسلم كتب إلى أن أزوجه أم حبيبة بنت أبي سفيان فأجبت إلى ما دعا إليه رسول الله صلى الله عليه وسلم وزوجته أم حبيبة فبارك الله لرسوله ودفع النجاشي الدنانير إلى خالد وروت عن النبي صلى الله عليه وسلم روى عنها أخوها معاوية بن أبي سفيان وكان سألها هل كان النبي صلى الله عليه وسلم يصلي في الثوب الذي يجامع فيه قالت نعم إذا لم ير فيه أذى وروى عنها غيره أخبرنا إبراهيم بن محمد وغيره قالوا بإسنادهم عن أبي عيسى الترمذي حدثنا علي بن حجر أخبرنا يزيد بن هارون عن محمد بن عبد الله الشعبي عن أبيه عن عنبسة بن أبي سفيان عن أم حبيبة قالت قال رسول الله صلى الله عليه وسلم من صلى قبل الظهر أربعا وبعده أربعا حرمه الله عز وجل على النار أخرجها الثلاثة'
WHERE id = 52
  AND content_ar LIKE '(ب د ع) رملة بنت أبي%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 52;

-- id=53  صفية بنت حيي بن أخطب
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 53;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'صفية بنت حيي بن أخطب بن سعنة بن ثعلبة بن عبيد بن كعب ابن الخزرج بن أبي حبيب بن النضير بن النحام بن ناخوم وقيل تنخوم وقيل نخوم والأول قاله اليهود وهم أعلم بلسانهم وهم من بني إسرائيل من سبط لاوي بن يعقوب ثم من ولد هارون بن عمران أخي موسى صلى الله عليهم وأم صفية برة بنت سموأل وكانت زوج سلام بن مشكم اليهودي ثم خلف عليها كنانة بن أبي الحقيق وهما شاعران فقتل عنها كنانة يوم خيبر روى أنس بن مالك أن رسول الله صلى الله عليه وسلم لما افتتح خيبر وجمع السبي أتاه دحية بن خليفة فقال أعطني جارية من السبي قال اذهب فخذ جارية فذهب فأخذ صفية قيل يا رسول الله إنها سيدة قريظة والنضير ما تصلح إلا لك فقال له رسول الله صلى الله عليه وسلم خذ جارية من السبي غيرها وأخذها رسول الله صلى الله عليه وسلم واصطفاها وحجبها وأعتقها وتزوجها وقسم لها وكانت عاقلة من عقلاء النساء أخبرنا أبو جعفر بإسناده عن يونس عن ابن إسحاق قال حدثني والدي إسحاق بن يسار قال لما افتتح رسول الله صلى الله عليه وسلم القموص حصن ابن أبي الحقيق أتي بصفية بنت حيي ومعها ابنة عم لها جاء بهما بلال فمر بهما على قتلى من قتلى يهود فلما رأتهم التي مع صفية صكت وجهها وصاحت وحثت التراب على رأسها فقال رسول الله صلى الله عليه وسلم أغربوا هذه الشيطانة عني وأمر رسول الله صلى الله عليه وسلم بصفية فحيزت خلفه وغطى عليها ثوبه فعرف الناس أنه قد اصطفاها لنفسه فقال رسول الله صلى الله عليه وسلم لبلال حين رأى من اليهودية ما رأى يا بلال أنزعت منك الرحمة حتى تمر بامرأتين على قتلاهما وقد كانت صفية قبل ذلك رأت أن قمرا قد وقع في حجرها فذكرت ذلك لأبيها فضرب وجهها ضربة أثرت فيه وقال إنك لتمدين عنقك إلى أن تكوني عند ملك العرب فلم يزل الأثر في وجهها حتى أتى بها رسول الله صلى الله عليه وسلم فسألها عنه فأخبرته الخبر أخبرنا غير واحد

بإسنادهم عن أبي عيسى قال حدثنا قتيبة أخبرنا أبو عوانة عن قتادة وعبد العزيز بن صهيب عن أنس أن رسول الله صلى الله عليه وسلم أعتق صفية وجعل عتقها صداقها قال وأخبرنا محمد بن عيسى أخبرنا بندار بن عبد الصمد أخبرنا هاشم بن سعيد الكوفي أخبرنا كنانة حدثتنا صفية بنت حيي قالت دخل علي رسول الله صلى الله عليه وسلم وقد بلغني عن حفصة وعائشة كلام فذكرت ذلك لرسول الله صلى الله عليه وسلم فقال ألا قلت وكيف تكونان خيرا مني وزوجي محمد وأبي هارون وعمي موسى وكان بلغها أنهما قالتا نحن أكرم على رسول الله صلى الله عليه وسلم منها نحن أزواج رسول الله صلى الله عليه وسلم وبنات عمه أخبرنا عبد الوهاب بن أبي حبة بإسناده عن عبد الله بن أحمد حدثني أبي حدثنا عبد الرزاق أخبرنا جعفر بن سليمان عن ثابت قال حدثتني شميسة أو سمية قال عبد الرزاق وهي في كتابي سمية عن صفية بنت حيي أن النبي صلى الله عليه وسلم حج بنسائه فلما كان ببعض الطريق برك بصفية جملها فبكت وجاء رسول الله صلى الله عليه وسلم حين أخبر بذلك فجعل يمسح دموعها بيده وجعلت تزداد بكاء وهو ينهاها فنزل رسول الله صلى الله عليه وسلم بالناس فلما كان عند الرواح قال لزينب بنت جحش يا زينب أقفري أختك جملا وكانت من أكثرهن ظهرا قالت أنا أقفر يهوديتك فغضب النبي صلى الله عليه وسلم حين سمع ذلك منها فلم يكلمها حتى قدم مكة وأيام منى في سفره حتى رجع إلى المدينة ومحرم وصفر فلم يأتها ولم يقسم لها ويئست منه فلما كان شهر ربيع الأول دخل عليها فلما رأت ظله قالت هذا ظل رجل وما يدخل على رسول الله صلى الله عليه وسلم فدخل النبي صلى الله عليه وسلم فلما رأته قالت يا رسول الله ما أصنع قال وكانت لها جارية تخبؤها من النبي صلى الله عليه وسلم فقالت فلانة لك قال فمشى النبي صلى الله عليه وسلم إلى سرير صفية وكان قد رفع فوضه بيده ورضي عن أهله وروى عنها علي بن الحسين قالت جئت إلى النبي صلى الله عليه وسلم أتحدث عنده وكان معتكفا في المسجد فقام معي يبلغني بيتي فلقيه رجلان من الأنصار قالت فلما رأيا رسول الله صلى الله عليه وسلم رجعا فقال تعاليا فإنها صفية فقالا نعوذ بالله سبحان الله يا رسول الله فقال إن الشيطان ليجري من ابن آدم مجرى الدم وتوفيت سنة ست وثلاثين وقيل سنة خمسين أخرجها الثلاثة'
WHERE id = 53
  AND content_ar LIKE '(ب د ع) صفية بنت حيي%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 53;


