-- id=54  ميمونة بنت الحارث
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 54;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'ميمونة بنت الحارث بن خزن الهلالية تقدم نسبها عن أختها لبابة وميمونة زوج النبي صلى الله عليه وسلم وقد تقدم ذكر أخواتها لبابة الكبرى ولبابة الصغرى وأسماء بنت عميس وغيرهن وكان اسم ميمونة برة فسماها رسول الله صلى الله عليه وسلم ميمونة قال كريب عن ابن عباس وهي خالته وخالة خالد بن الوليد وكانت قبل رسول الله صلى الله عليه وسلم عند أبي رهم بن عبد العزى بن عبد ود بن مالك بن حسل ابن عامر بن لؤي وقيل عند سخبرة بن أبي رهم وقيل كانت عند حويطب بن عبد العزى وقيل فروة بن عبد العزى الأسدي أسد بن خزيمة قاله قتادة تزوجها رسول الله صلى الله عليه وسلم بعد زوجها سنة سبع في عمرة القضاء في ذي القعدة فأرسل رسول الله صلى اله عليه وسلم جعفر بن أبي طالب إليها فخطبها فجعلت أمرها إلى العباس بن عبد المطلب فزوجها من رسول الله صلى الله عليه وسلم وقيل بل العباس قال لرسول الله صلى الله عليه وسلم أن ميمونة بنت الحارث قد تأيمت من أبي رهم بن عبد العزى هل لك أن تزوجها فتزوجها رسول الله صلى الله عليه وسلم أخبرنا أبو جعفر بإسناده عن يونس بن بكير عن ابن إسحاق قال ثم تزوج رسول الله صلى الله عليه وسلم بعد صفية ميمونة بنت الحارث الهلالية وكانت قبله عند أبي رهم بن عبد العزى قال يونس حدثنا جعفر بن برقان عن ميمون بن مهران عن يزيد بن الأصم قال تزوج رسول الله صلى الله عليه وسلم ميمونة وهو حلال في قبة لنا وماتت فيها ويزيد هو ابن أخت ميمونة وقيل تزوجها وهو محرم أخبرنا غير واحد بإسنادهم عن محمد بن عيسى حدثنا حميد بن مسعدة حدثنا سفيان بن حبيب عن هشام بن حسان عن عكرمة عن ابن عباس أن النبي صلى الله عليه وسلم تزوج ميمونة وهو محرم ولهذا الاختلاف اختلف الفقهاء في نكاح المحرم وقال بعضهم تزوجها رسول الله صلى الله عليه وسلم وهو حلال وظهر أمر تزويجها وهو محرم ثم بنى بها وهو حلال بسرف بطريق مكة وماتت بسرف أيضا حيث بنى بها رسول الله صلى الله عليه وسلم ودفنت هناك ولما فرغ رسول الله صلى الله عليه وسلم من عمرته أقام بمكة ثلاثا فأتاه سهيل بن عمرو في نفر من أهل مكة

فقالوا يا محمد اخرج عنا فاليوم آخر شرطك وكان شرط في الحديبية أن يعتمر من قابل ويقيم بمكة ثلاثا فقال دعوني أبتني بأهلي وأصنع لكم طعاما فقالوا لا حاجة لنا بطعامك فخرج فبنى بها بسرف قريب مكة وقال بان شهاب وقتادة هي التي وهبت نفسها للنبي صلى الله عليه وسلم فأنزل الله تعالى وامرأة مؤمنة إن وهبت نفسها للنبي صلى الله عليه وسلم الآية والصحيح ما تقدم أخبرنا أبو منصور بن مكارم بن أحمد بإسناده عن المعافى بن عمران عن هشام بن سعد عن زيد بن أسلم عن عطاء بن يسار عن ميمونة زوج النبي صلى الله عليه وسلم أنه سئل عن الجبن فقال اقطع بالسكين وسم الله تعالى وكل وتوفيت سنة إحدى وخمسين وقيل سنة ثلاث وستين عام الحرة وصلى عليها ابن عباس ودخل قبرها هو ويزيد بن الأصم وعبد الله بن شداد بن الهاد وهم أولاد أخواتها ونزل معهم عبيد الله الخولاني وكان يتيما في حجرها أخرجها الثلاثة'
WHERE id = 54
  AND content_ar LIKE '(ب د ع) ميمونة بنت ا%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 54;

-- id=55  زيد بن ثابت
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 55;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'زيد بن ثابت بن الضحاك بن زيد بن لوذان بن عمرو بن عبد بن عوف بن غنم بن مالك بن النجار الأنصاري الخزرجي ثم النجاري أمه النوار بنت مالك بن معاوية بن عدي بن عامر بن غنم بن عدي بن النجار كنيته
أبو سعيد وقيل أبو عبد الرحمن وقيل أبو خارجة وكان عمره لما قدم النبي صلى الله عليه وسلم المدينة إحدى عشرة سنة وكان يوم بعاث ابن ست سنين وفيها قتل أبوه واستصغره رسول الله صلى الله عليه وسلم يوم بدر فرده وشهد أحدا وقيل لم يشهدها وإنما شهد الخندق أول مشاهده وكان ينقل التراب مع المسلمين فقال رسول الله صلى الله عليه وسلم أنه نعم الغلام وكانت راية بني مالك بن النجار يوم تبوك مع عمارة بن حزم فأخذها رسول الله صلى الله عليه وسلم ودفعها إلى زيد بن ثابت فقال عمارة يا رسول الله بلغك عني شئ قال لا ولكن القرآن مقدم وزيد أكثر أخذا للقرآن منك وكان زيد يكتب لرسول الله صلى الله عليه وسلم الوحي وغيره وكانت ترد على رسول الله صلى الله عليه وسلم كتب بالسريانية فأمر زيدا فتعلمها وكتب بعد النبي صلى الله عليه وسلم لأبي بكر وعمر وكتب لهما معه معيقيب الدوسي أيضا واستخلفه على المدينة ثلاث مرات مرتين في حجتين ومرة في مسيره إلى الشام وكان عثمان يستخلفه أيضا إذا حج ورمي يوم اليمامة بسهم فلم يضره وكان أعلم الصحابة بالفرائض فقال رسول الله صلى الله عليه وسلم أفرضكم زيد فأخذ الشافعي بقوله في الفرائض عملا بهذا الحديث وكان من أعلم الصحابة والراسخين في العلم وكان من أفكه الناس إذا خلا مع أهله وأزمتهم إذا كان في القوم وكان على بيت المال لعثمان فدخل عثمان يوما فسمع مولى لزيد يغني فقال عثمان من هذا فقال زيد مولاي وهيب ففرض له عثمان ألفا وكان زيد عثمانيا ولم يشهد مع علي شيئا من حروبه وكان يظهر فضل علي وتعظيمه روى عنه من الصحابة ابن عمر وأبو سعيد وأبو هريرة وأنس وسهل بن سعد وسهل بن حنيف وعبد الله بن يزيد الخطمي ومن التابعين سعيد ابن المسيب والقاسم بن محمد وسليمان بن يسار وأبان بن عثمان وبشر بن سعيد وخارجة وسليمان ابنا زيد بن ثابت وغيرهم أخبرنا أبو الفضل عبد الله بن أحمد بن عبد القاهر الخطيب قال أخبرنا أبو بكر بن بدران الحلواني أخبرنا أبو محمد الحسن ابن محمد الفارسي أخبرنا أبو الحسن علي بن محمد بن أحمد بن كيسان النحوي أخبرنا يوسف بن يعقوب القاضي أخبرنا مسلم بن إبراهيم أخبرنا هشام الدستواني أخبرنا قتادة عن أنس عن زيد بن ثابت قال تسحرنا مع رسول الله صلى الله عليه وسلم ثم قام إلى الصلاة قلت كم كان بين الآذان والسحور قال قدر خمسين آية وتوفي سنة خمس وأربعين وقيل اثنتان وقيل ثلاث وأربعين وقيل سنة إحدى وخمسين وقيل اثنتان 
وقيل خمس وخمسون وصلى عليه مروان بن الحكم ولما توفي قال أبو هريرة اليوم مات حبر هذه الأمة وعسى الله أن يجعل في ابن عباس منه خلفا وهو الذي كتب القرآن في عهد أبي بكر وعثمان رضي الله عنهما'
WHERE id = 55
  AND content_ar LIKE '(ب د ع) زيد بن ثابت %'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 55;

-- id=56  أبيّ بن كعب
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 56;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'أبي بن كعب بن قيس بن عبيد بن زيد بن معاوية بن عمرو بن مالك ابن النجار واسمه تيم اللات وقيل تيم الله بن ثعلبة بن عمرو بن الخزرج الأكبر الأنصاري الخزرجي المعاوي وإنما سمي النجار لأنه اختتن بقدوم وقيل ضرب وجه رجل بقدوم فنجره فقيل له النجار وبنو معاوية بن عمرو يعرفون ببني حديلة وهي أم معاوية نسب ولده إليها وهي حديلة بنت مالك بن زيد بن حبيب بن عبد حارثة بن مالك بن عضب بن جشم بن الخزرج وأم أبي سهيلة بنت الأسود بن حرام بن عمرو ابن زيد مناة بن عدي بن عمرو بن مالك بن النجار تجتمع هي وأبوه في عمرو بن مالك ابن النجار وهي عمة أبي طلحة زيد بن سهل بن الأسود بن حرام الأنصاري زوج أم سليم وله كنيتان أبو المنذر كناه بها النبي صلى الله عليه وسلم وأبو الطفيل كناه بها عمر بن الخطاب بابنه الطفيل وشهد العقبة وبدرا وكان عمر يقول أبي سيد المسلمين روى عنه عبادة بن الصامت وابن عباس وعبد الله بن خباب وابنه الطفيل بن أبي أخبرنا إبراهيم بن محمد وإسماعيل بن عبيد وأبو جعفر بإسنادهم عن الترمذي قال حدثنا محمد بن بشار أنبأنا عبد الوهاب الثقفي أنبأنا خالد الحذاء عن أبي قلابة عن أنس بن مالك أن النبي قال لأبي بن كعب إن الله أمرني أن أقرأ عليك لم يكن الذين كفروا قال آلله سماني لك قال نعم فجعل أبي يبكي وروى عبد الرحمن بن أبزى عن أبي أن النبي صلى الله عليه وسلم قال نحوه قال عبد الرحمن قلت لأبي وفرحت بذلك قال وما يمنعني وهو يقول قل بفضل الله وبرحمته فبذلك فليفرحوا هو خير مما يجمعون قال الترمذي وبالإسناد المذكور حدثنا ابن وكيع حدثنا حميد بن عبد الرحمن عن داود العطار عن معمر عن قتادة عن أنس أن النبي صلى الله عليه وسلم قال أرحم أمتي بأمتي أبو بكر وأشدهم في دين الله عمر وأصدقهم حياء عثمان وأعلمهم بالحلال والحرام معاذ بن جبل وأفرضهم زيد بن ثابت وأقرأهم أبي بن كعب ولكل أمة أمين
وأمين هذه الأمة أبو عبيدة بن الجراح وقد رواه أبو قلابة عن أنس نحوه وزاد فيه وأقضاهم علي وقد روى عن زر بن حبيش أنه لزم أبي بن كعب وكانت فيه شراسة فقلت له اخفض لي جناحك رحمك الله أخبرنا أبو منصور بن السيحي المعدل أخبرنا أبو البركات محمد بن محمد بن خميس الجهني الموصلي أخبرنا أبو نصر بن طوق أخبرنا ابن المرجي أخبرنا أحمد بن علي بن المثنى حدثنا أبو عبد الله محمد بن عبدة بن حرب حدثنا أبو علي الحسن بن قزعة أخبرنا سفيان بن حبيب أخبرنا سعيد عن ثوير بن أبي فاختة عن أبيه عن الطفيل عن أبيه يعني أبي بن كعب قال سمع النبي صلى الله عليه وسلم يقرأ وألزمهم كلمة التقوى قال شهادة أن لا إله إلا الله وروى الحسن بن صالح عن مطرف عن الشعبي عن مسروق قال كان أصحاب القضاء من أصحاب رسول الله ستة عمر وعلي وعبد الله وأبي وزيد وأبو موسى قال أبو عمر قال محمد بن سعد عن الواقدي أول من كتب لرسول الله مقدمه المدينة أبي بن كعب وهو أول من كتب في آخر الكتاب وكتب فلان بن فلان فإذا لم يحضر أبي كتب زيد بن ثابت وأول من كتب من قريش عبد الله بن سعد بن أبي سرح ثم ارتد ورجع إلى مكة فنزل فيه ومن أظلم ممن افترى على الله كذبا أو قال أوحي إلي ولم يوح إليه شئ وكان من المواظبين على كتاب الرسائل عبد الله بن الأرقم الزهري وكان الكاتب لعهوده صلى الله عليه وسلم إذا عاهد وصلحه إذا صالح علي بن أبي طالب وممن كتب لرسول الله أبو بكر الصديق وعمر بن الخطاب وعثمان بن عفان والزبير بن العوام وخالد وأبان ابنا سعيد بن العاصي وحنظلة الأسيدي والعلاء بن الحضرمي وخالد بن الوليد وعبد الله بن رواحة ومحمد بن مسلمة وعبد الله بن عبد الله بن أبي ابن سلول والمغيرة بن شعبة وعمرو ابن العاص ومعاوية بن أبي سفيان وجهم بن الصلت ومعيقيب بن أبي فاطمة وشرحبيل بن حسنة قال أبو نعيم اختلف في وقت وفاة أبي فقيل توفي سنة اثنتين وعشرين في خلافة عمر وقيل سنة ثلاثين في خلافة عثمان قال وهو الصحيح لأن زر بن حبيش لقيه في خلافة عثمان وقال أبو عمر مات سنة تسع عشرة وقيل سنة عشرين وقيل سنة اثنتين وعشرين وقيل إنه مات في خلافة عثمان سنة اثنتين وثلاثين والأكثر إنه مات في خلافة عمر وكان أبيض الرأس واللحية لا يغير شيبه أخرجه ثلاثتهم * حديلة بضم الحاء المهملة وفتح الدال وحبيش بضم الحاء المهملة وفتح الباء الموحدة وسكون الياء تحتها نقطتان وآخره شين معجمة والسيحي بكسر السين المهملة وبعدها ياء تحتها 
نقطتان ثم حاء مهملة وثوير بضم الثاء المثلثة تصغير ثور وسرح بالسين والحاء المهملتين'
WHERE id = 56
  AND content_ar LIKE '(ب د ع) أبي بن كعب ب%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 56;


-- الخطوة 2 (v2: LIKE بالبداية + معاملة مستقلة لكل صف) - دفعة 15/31 (3 صفوف)

-- id=57  معاوية بن أبي سفيان
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 57;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'معاوية بن صخر بن حرب بن أمية بن عبد شمس بن عبد مناف القرشي الأموي وهو معاوية بن أبي سفيان وأمه هند بنت عتبة بن ربيعة بن عبد شمس يجتمع أبوه وأمه في عبد شمس وكنيته أبو عبد الرحمن أسلم هو وأبوه وأخوه يزيد وأمه هند في الفتح وكان معاوية يقول إنه أسلم عام القضية وإنه لقي رسول الله صلى الله عليه وسلم مسلما وكتم إسلامه من أبيه وأمه وشهد مع رسول الله صلى الله عليه وسلم حنينا وأعطاه من غنائم هوازن مائة بعير وأربعين أوقية وكان هو وأبوه من المؤلفة قلوبهم وحسن إسلامهما وكتب لرسول الله صلى الله عليه وسلم ولما سير أبو بكر رضي الله عنه الجيوش إلى الشام سار معاوية مع أخيه يزيد بن أبي سفيان فلما مات يزيد استخلفه على عمله بالشام وهو دمشق فلما بلغ خبر وفاة يزيد إلى عمر قال لأبي سفيان أحسن الله عزاك في يزيد رحمه الله فقال له أبو سفيان من وليت مكانه قال
أخاه معاوية قال وصلتك رحم يا أمير المؤمنين أخبرنا إبراهيم بن محمد وغيره بإسنادهم إلى أبي عيسى حدثنا محمد بن يحيى حدثنا أبو مسهر عن سعيد بن عبد العزيز عن ربيعة بن يزيد عن عبد الرحمن بن أبي عميرة وكان من أصحاب النبي صلى الله عليه وسلم أنه قال لمعاوية اللهم اجعله هاديا مهديا واهد به قال وأخبرنا أبو عيسى حدثنا سويد بن نصر أخبرنا عبد الله وهو ابن المبارك أخبرنا يونس عن الزهري أخبرنا عبيد بن عبد الرحمن أنه سمع معاوية خطب بالمدينة فقال أين علماؤكم يا أهل المدينة سمعت رسول الله صلى الله عليه وسلم ينهى عن هذه القصة ويقول إنما هلكت بنو إسرائيل حين اتخذها نساؤهم وقال ابن عباس معاوية فقيه وقال ابن عمر ما رأيت أحدا بعد رسول الله صلى الله عليه وسلم أسود من معاوية فقيل له أبو بكر وعمر وعثمان وعلي فقال كانوا والله خيرا من معاوية وأفضل ومعاوية أسود ولما دخل عمر بن الخطاب رضي الله عنه الشام ورأى معاوية قال هذا كسرى العرب أخبرنا يحيى بن محمود وغيره بإسنادهما عن مسلم قال أخبرنا محمد ابن مثنى ومحمد بن بشار واللفظ لابن مثنى حدثنا أمية بن خالد حدثنا شعبة عن أبي حمزة القصاب عن ابن عباس قال كنت ألعب مع الصبيان فجاء رسول الله صلى الله عليه وسلم فتواريت خلف باب قال فجاء فحطأني حطأة وقال اذهب فادع لي معاوية قال فجئت فقلت هو يأكل ثم قال اذهب فادع لي معاوية قال فجئت فقلت هو يأكل فقال لا أشبع الله بطنه أخرج مسلم هذا الحديث بعينه لمعاوية وأتبعه بقول رسول الله صلى الله عليه وسلم إني اشترطت على ربي فقلت إنما أنا بشر أرضى كما يرضى البشر وأغضب كما يغضب البشر فأيما أحد دعوت عليه من أمتي بدعوة أن يجعلها له ظهورا وزكاة وقربة يقربه بها يوم القيامة ولم يزل واليا على ما كان أخوه يتولاه بالشام خلافة عمر فلما استخلف عثمان جمع له الشام جميعه ولم يزل كذلك إلى أن قتل عثمان فانفرد بالشام ولم يبايع عليا وأظهر الطلب بدم عثمان فكان وقعة صفين بينه وبين علي وهي مشهورة وقد استقصينا ذلك في كتابنا الكامل في التاريخ ثم لما قتل علي واستخلف الحسن بن علي سار معاوية إلى العراق وسار إليه الحسن بن علي فلما رأى الحسن الفتنة وأن الأمر عظيم تراق فيه الدماء ورأى اختلاف أهل العراق سلم الأمر إلى معاوية وعاد إلى المدينة وتسلم معاوية العراق وأتى الكوفة فبايعه الناس واجتمعوا عليه فسمي عام الجماعة فبقي خليفة عشرين سنة وأميرا عشرين سنة لأنه ولي دمشق أربع سنين من خلافة عمر واثنتي عشرة سنة خلافة عثمان مع ما أضاف إليه من باقي الشام وأربع سنين تقريبا أيام خلافة علي وستة أشهر خلافة الحسن وسلم إليه الحسن الخلافة سنة إحدى وأربعين وقيل سنة أربعين والأول أصح وتوفي معاوية النصف من رجب سنة ستين وهو ابن ثمان وسبعين سنة وقيل ابن ست وثمانين سنة وقيل توفي يوم الخميس لثمان بقين من رجب سنة تسع وخمسين وهو ابن اثنتين وثمانين سنة والأصح في وفاته أنها سنة ستين ولما مرض كان ابنه يزيد غائبا ولما حضره الموت أوصى أن يكفن في قميص كان رسول الله صلى الله عليه وسلم قد كساه إياه وأن يجعل مما يلي جسده وكان عنده قلامة أظفار رسول الله صلى الله عليه وسلم فأوصى أن تسحق وتجعل في عينيه وفمه وقال افعلوا ذلك وخلوا بيني وبين أرحم الراحمين ولما نزل به الموت قال ليتني كنت رجلا من قريش بذي طوى وإني لم آل من هذا الأمر شيئا ولما مات أخذ الضحاك بن قيس أكفانه وصعد المنبر وخطب الناس وقال إن أمير المؤمنين معاوية كان حد العرب وعود العرب قطع الله به الفتنة وملكه على العباد وسير جنوده في البر والبحر وكان عبدا من عبيد الله دعاه فأجابه وقد قضى نحبه وهذه أكفانه فنحن مدرجوه ومدخلوه قبره ومخلوه وعمله فيما بينه وبين ربه إن شاء رحمه وإن شاء عذبه وصلى عليه الضحاك وكان يزيد غائبا بحوارين فلما نقل معاوية أرسل إليه الضحاك فقدم وقد مات معاوية فقال

جاء البريد بقرطاس يحث بهفأوجس القلب من قرطاسه فزعاقلنا لك الويل ماذا في صحيفتكمقالوا الخليفة أمسى مثبتا وجعا
وهي أكثر من هذا وكان معاوية أبيض جميلا إذا ضحك انقلبت شفته العليا وكان يخضب روى عنه جماعة من الصحابة ابن عباس والخدري وأبو الدرداء وجرير والنعمان بن بشير وابن عمر وابن الزبير وغيرهم ومن التابعين أبو سلمة وحميد ابنا عبد الرحمن وعروة وسالم وعلقمة بن وقاص وابن سيرين والقاسم بن محمد وغيرهم روي عنه أنه قال ما زلت أطمع في الخلافة مذ قال لي رسول الله صلى الله عليه وسلم أن وليت فأحسن وروى عبد الرحمن بن أبزى عن عمر أنه قال هذا الأمر في أهل بدر ما بقي منهم أحد ثم في أهل أحد ما بقي منهم أحد ثم في كذا وكذا 
وليس فيها لطليق ولا لولد طليق ولا لمسلمة الفتح شئ أخرجه الثلاثة'
WHERE id = 57
  AND content_ar LIKE '(ب د ع) معاوية بن صخ%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 57;

-- id=58  خالد بن سعيد بن العاص
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 58;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'خالد بن سعيد بن العاص ابن أمية بن عبد شمس بن عبد مناف بن قصي القرشي الأموي يكنى أبا سعيد أمه أم خالد بن حباب بن عبد يا ليل بن ناشب بن غيرة من ثقيف أسلم قديما يقال أنه أسلم بعد أبي بكر الصديق رضي الله عنه فكان ثالثا أو رابعا وقيل كان خامسا وقال ضمرة ابن ربيعة كان إسلام خالد مع إسلام أبي بكر وقالت أم خالد بنت خالد بن سعيد بن العاص كان أبي خامسا في الإسلام قلت من تقدمه قالت علي بن أبي طالب وأبو بكر وزيد بن حارثة وسعد بن أبي وقاص رضي الله عنهم وكان سبب إسلامه أنه رأى في النوم أنه وقف على شفير النار فذكر من سعتها ما الله أعلم به وكأن أباه يدفعه فيها ورأى رسول الله صلى الله عليه وسلم آخذا بحقويه لا يقع فيها ففزع وقال أحلف إنها لرؤيا حق ولقي أبا بكر رضي الله عنه فذكر ذلك له فقال له أبو بكر أريد بك خير هذا
رسول الله صلى الله عليه وسلم فاتبعه فإنك ستتبعه في الإسلام الذي يحجزك من أن تقع في النار وأبوك واقع فيها فلقى رسول الله صلى الله عليه وسلم وهو بأجياد فقال يا محمد إلى من تدعو قال أدعو إلى الله وحده لا شريك له وأن محمدا عبده ورسوله وتخلع ما أنت عليه من عبادة حجر لا يسمع ولا يبصر ولا يضر ولا ينفع ولا يدري من عبده ممن لم يعبده قال خالد فإني أشهد أن لا إله إلا الله وأشهد أنك رسول الله فسر رسول الله صلى الله عليه وسلم بإسلامه وتغيب خالد وعلم أبوه اسلامه فأرسل في طلبه من بقي من ولده ولم يكونوا أسلموا فوجدوه فأتوا به أباه أبا أحيحة سعيدا فسبه وبكته وضربه بعصا في يده حتى كسرها على رأسه وقال اتبعت محمدا وأنت ترى خلافه قومه وما جاء به من عيب آلهتهم وعيب من مضى من آبائهم قال قد والله تبعته على ما جاء به فغضب أبوه ونال منه وقال اذهب يا لكع حيث شئت والله لأمنعنك القوت فقال خالد إن منعتني فإن الله يرزقني ما أعيش به فأخرجه وقال لبنيه لا يكلمه أحد منكم إلا صنعت به ما صنعت بخالد فانصرف خالد إلى رسول الله صلى الله عليه وسلم فكان يلزمه ويعيش معه وتغيب عن أبيه في نواحي مكة حتى خرج المسلمون إلى أرض الحبشة في الهجرة الثانية فخرج معهم وكان أبوه شديدا على المسلمين وكان أعز من بمكة فمرض فقال لئن الله رفعني من مرضي هذا لا يعبد إله ابن أبي كبشة بمكة فقال ابنه خالد عند ذلك اللهم لا ترفعه فتوفي في مرضه ذلك وهاجر خالد إلى الحبشة ومعه امرأته أميمة بنت خالد الخزاعية وولد له بها ابنه سعيد بن خالد وابنته أم خالد واسمها أمة وهاجر معه إلى أرض الحبشة أخو عمرو بن سعيد وقدما على النبي صلى الله عليه وسلم بخيبر مع جعفر بن أبي طالب في السفينتين فكلم النبي صلى الله عليه وسلم المسلمين فأسهموا لهم وشهد مع النبي صلى الله عليه وسلم القضية وفتح مكة وحنينا والطائف وتبوك وبعثه رسول الله صلى الله عليه وسلم عاملا على صدقات اليمن وقيل على صدقات مذحج وعلى صنعاء فتوفي النبي صلى الله عليه وسلم وهو عليها ولم يزل خالد وأخواه عمرو وأبان على أعمالهم التي استعملهم عليها رسول الله صلى الله عليه وسلم حتى توفي رسول الله صلى الله عليه وسلم فلما توفي رجعوا عن أعمالهم فقال لهم أبو بكر ما لكم رجعتم ما أحد أحق بالعمل من عمال رسول الله صلى الله عليه وسلم ارجعوا إلى أعمالكم فقالوا نحن بنو أبي أحيحة لا نعمل لأحد بعد رسول الله 
صلى الله عليه وسلم أبدا وكان خالد على اليمن كما ذكرناه وأبان على البحرين وعمرو على تيماء وخيبر وقرى عربية وتأخر خالد وأخوه أبان عن بيعة أبي بكر رضي الله عنه فقال لبني هاشم إنكم لطوال الشجر طيبوا الثمر ونحن تبع لكم فلما بايع بنو هاشم أبا بكر بايعه خالد وأبان ثم استعمل أبو بكر خالدا على جيش من جيوش المسلمين حين بعثهم إلى الشام فقتل بمرج الصفر في خلافة أبي بكر رضي الله عنه وقيل كانت وقعة مرج الصفر سنة أربع عشرة في صدر خلافة عمر وقيل بل كان قتله في وقعة أجنادين بالشام قبل وفاة أبي بكر بأربع وعشرين ليلة وقد اختلف أصحاب السير في وقعة أجنادين ووقعة الصفر ووقعة اليرموك أيها قبل الأخرى والله أعلم أخرجه الثلاثة قال الغساني * قرى عربية كذا هو غير منون لهذه التي بالحجاز كذا قيده غير واحد من أهل العلم'
WHERE id = 58
  AND content_ar LIKE '(ب د ع) خالد بن سعيد%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 58;

-- id=59  حنظلة بن الربيع (حنظلة الكاتب)
SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 59;

BEGIN;

UPDATE public.stories
SET source_codes = 'ب د ع',
    content_ar = 'حنظلة بن الربيع وقيل بن ربيعة والأول أكثر من صيفي بن رياح بن الحارث بن مخاشن بن معاوية بن شريف ابن جروة بن أسيد بن عمرو بن تميم التميمي يكنى أبا ربعي ويقال له حنظلة الأسيدي والكتاب لأنه كان يكتب للنبي صلى الله عليه وسلم وهو ابن أخي أكثم بن صيفي وهو ممن تخلف عن علي رضي الله عنه في قتال الجمل بالبصرة روى عنه أبو عثمان النهدي ويزيد بن الشخير ومرقع بن صيفي أخبرنا أبو جعفر عبيد الله بن أحمد ابن علي بإسناده إلى الترمذي أبي عيسى قال حدثنا بشر بن هلال البصري حدثنا جعفر بن سليمان قال الترمذي وحدثنا هارون بن عبد الله البزار حدثنا سيار قالا حدثنا سعيد الجريري والمعنى واحد عن أبي عثمان عن حنظلة الأسيدي وكان من كتاب النبي صلى الله عليه وسلم أنه مر بأبي بكر رضي الله عنه وهو يبكي فقال مالك يا حنظلة قال نافق حنظلة يا أبا بكر نكون عند رسول الله صلى الله عليه وسلم يذكرنا بالنار والجنة كانا رأى عين فإذا رجعنا عافسنا الأزواج والضيعة ونسينا كثيرا قال فوالله إنا كذلك انطلق بنا إلى رسول الله صلى الله عليه وسلم فانطلقنا فلما رآه رسول الله صلى الله عليه وسلم قال مالك يا حنظلة قال نافق حنظلة يا رسول الله نكون عندك تذكرنا بالنار والجنة كانا رأى عين فإذا رجعنا عافسنا الأزواج والضيعة ونسينا كثيرا قال فقال النبي صلى الله عليه وسلم لو تدومون على الحال التي تقومون بها من عندي لصافحتكم الملائكة في مجالسكم وفي طرقكم وعلى فرشكم ولكن يا حنظلة ساعة وساعة رواه سفيان عن الجريري مثله ورواه أبو داود الطيالسي عن عمران عن قتادة عن يزيد بن عبد الله بن الشخير عن حنظلة نحوه أخبرنا عبيد الله بن أحمد ابن علي بإسناده إلى يونس بن بكير عن ابن إسحاق قال بعث رسول الله صلى الله عليه وسلم حنظلة بن الربيع بن صيفي بن أخي أكثم بن صيفي إلى أهل الطائف أتريدون الصلح أم لا فلما توجه إليهم قال رسول الله صلى الله عليه وسلم ائتموا بهذا وأشباهه ثم انتقل إلى قرقيسيا فمات بها ولما توفي حنظلة جزعت عليه امرأته فنهاها جاراتها وقلن لها يحبط أجرك فقالت

تعجبت دعد لمحزونةتبكي على ذي شيبة شاحبإن تساليني اليوم ما شفنيأخبرك قولا ليس بالكاذبإن سواد العين أودى بهحزن على حنظلة الكاتب
أخرجه الثلاثة * شريف بضم الشين المعجمة وفتح الراء وجروة بالجيم والراء وأسيد بضم الهمزة وفتح السين وتشديد الياء تحتها نقطتان والمحدثون ينسبون إليه بالتشديد أيضا وأهل العربية يخففون ورباح بالباء الموحدة وقيل بالياء تحتها نقطتان والأول أكثر'
WHERE id = 59
  AND content_ar LIKE '(ب د ع) حنظلة بن الر%'
  AND source_codes IS NULL;

COMMIT;

SELECT id, source_codes, left(content_ar, 60) AS content_preview
FROM public.stories WHERE id = 59;


